create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role text not null default 'worker' check(role in('admin','worker')),active boolean default true,created_at timestamptz default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),name text not null,client_name text,client_phone text,address text,area_m2 numeric default 0,sell_price_m2 numeric default 0,status text default 'Yangi',created_at timestamptz default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,category text not null,item_name text not null,quantity numeric default 0,unit text,unit_price numeric default 0,total_amount numeric default 0,note text,expense_date date default current_date,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,amount numeric not null,note text,payment_date date default current_date,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.work_logs(id uuid primary key default gen_random_uuid(),worker_id uuid not null references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,work_description text not null,completed_m2 numeric default 0,arrived_at time,left_at time,work_date date default current_date,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.expenses enable row level security; alter table public.payments enable row level security; alter table public.work_logs enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and active=true)$$;
create policy "profile read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "admin project all" on public.projects for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "worker project read" on public.projects for select to authenticated using(true);
create policy "admin expense all" on public.expenses for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin payment all" on public.payments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "worklog read" on public.work_logs for select to authenticated using(public.is_admin() or worker_id=auth.uid()); create policy "worklog insert" on public.work_logs for insert to authenticated with check(worker_id=auth.uid()); create policy "worklog update" on public.work_logs for update to authenticated using(worker_id=auth.uid()) with check(worker_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),'worker') on conflict(id) do nothing; return new; end$$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Birinchi admin: update public.profiles set role='admin' where id='AUTH_USER_UUID';
